# RWDM_SOFTMOVE: SoftMove: move relative to a centre with a falloff distance. The script rwdm_softmove_script.txt is generated by rwdm_gen.py (the closed forms are in that file); every case moves each Point object
# from its closed-form image E_k to the origin and lists it: the app prints a coordinate within 1e-9 of an integer as that integer, so a
# passing case means every image lies within 1e-9 of the textbook formula (a residual of 1e-6 would read 1e-06; RWDM_*_sensitivity checks that).
if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
  RWDM_SOFTMOVE_OUT="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/rwdm_softmove_script.txt" 2>&1)" || { echo "$RWDM_SOFTMOVE_OUT" | tail -40; echo "FAIL RWDM_SOFTMOVE_run: script exited non-zero"; fail=1; RWDM_SOFTMOVE_OUT=""; }
else
  RWDM_SOFTMOVE_OUT="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/rwdm_softmove_script.txt" 2>&1)" || { echo "$RWDM_SOFTMOVE_OUT" | tail -40; echo "FAIL RWDM_SOFTMOVE_run: script exited non-zero"; fail=1; RWDM_SOFTMOVE_OUT=""; }
fi
rwdm_softmove_block() { awk -v name="$1" '$0 ~ ("Unknown command: RWDMBEGIN_" name "$") { on = 1; next } on && /Unknown command: RWDMBEGIN_/ { exit } on { print }' <<<"$RWDM_SOFTMOVE_OUT"; }
# rwdm_softmove_check NAME N DESC: the case listed exactly N points and every one of them is "0,0,0" (the residual to the closed form)
rwdm_softmove_check() {
  local blk npts zeros; blk="$(rwdm_softmove_block "$1")"
  npts="$({ grep -cE '^history: Object [0-9]+ \(point\)' <<<"$blk" || true; })"
  zeros="$({ grep -cE '^history:   0,0,0$' <<<"$blk" || true; })"
  if [ "$npts" = "$2" ] && [ "$zeros" = "$2" ]; then echo "ok   RWDM_SOFTMOVE_$1: $3 ($2 points, every one within 1e-9 of the closed form)"
  else echo "FAIL RWDM_SOFTMOVE_$1: $3 (listed $npts points, $zeros at residual 0; expected $2 and $2)"; fail=1; { grep -E '^history:   ' <<<"$blk" || true; } | head -12 | sed 's/^/     residual: /'; fi
}
# the last List (all 6 points) carries the residuals of ids 1, 5, 6 (must be 0,0,0) and the raw positions of ids 2..4 (moved up by a fraction of 4)
RWDM_SOFTMOVE_BLK="$(rwdm_softmove_block falloff)"
RWDM_SOFTMOVE_Y="$({ grep -E '^history:   [-0-9.e+]+,[-0-9.e+]+,[-0-9.e+]+$' <<<"$RWDM_SOFTMOVE_BLK" || true; } | tail -6)"
rwdm_softmove_pt() { sed -n "$1p" <<<"$RWDM_SOFTMOVE_Y" | sed 's/^history:   //'; }
if [ "$(rwdm_softmove_pt 1)" = "0,0,0" ] && [ "$(rwdm_softmove_pt 5)" = "0,0,0" ] && [ "$(rwdm_softmove_pt 6)" = "0,0,0" ]; then echo "ok   RWDM_SOFTMOVE_exact: the picked point moved by the full vector (0,4,0) and the points at distance 10 and 13 (>= radius) did not move (residual 0,0,0 within 1e-9)"
else echo "FAIL RWDM_SOFTMOVE_exact: residuals of the picked, the at-radius and the outside point were '$(rwdm_softmove_pt 1)' '$(rwdm_softmove_pt 5)' '$(rwdm_softmove_pt 6)' (expected 0,0,0 each)"; fail=1; fi
# ids 2..4 are the 2nd..4th rows of the last listing; their y is the moved fraction * 4, their x the original 2.5, 5, 7.5
RWDM_SOFTMOVE_OK=1; RWDM_SOFTMOVE_PREV=4
for i in 2 3 4; do
  p="$(rwdm_softmove_pt $i)"; x="${p%%,*}"; y="${p#*,}"; y="${y%%,*}"; ex="$(awk -v k="$i" 'BEGIN { printf "%g", 2.5 * (k - 1) }')"
  if ! awk -v x="$x" -v ex="$ex" -v y="$y" -v prev="$RWDM_SOFTMOVE_PREV" 'BEGIN { d = x - ex; if (d < 0) d = -d; exit !(d < 1e-9 && y > 0 && y < prev) }'; then RWDM_SOFTMOVE_OK=0; echo "     point $i: x=$x (expected $ex) y=$y (expected 0 < y < $RWDM_SOFTMOVE_PREV)"; fi
  RWDM_SOFTMOVE_PREV="$y"
done
if [ "$RWDM_SOFTMOVE_OK" = 1 ]; then echo "ok   RWDM_SOFTMOVE_falloff: inside the radius each point moves along the vector by a fraction strictly between 0 and 1 that strictly decreases with the distance from the picked point (x untouched)"
else echo "FAIL RWDM_SOFTMOVE_falloff: the falloff is not strictly between 0 and the full move and strictly decreasing"; fail=1; fi
# negative control: the same harness must SEE a 1e-6 error (point moved 1e-6 off its expected image reads 1e-06, not 0)
rwdm_softmove_sens() {
  local blk; blk="$(rwdm_softmove_block sensitivity)"
  if grep -qE '^history:   (0,0,)?[-0-9.e]*1e-06' <<<"$blk" && ! grep -qE '^history:   0,0,0$' <<<"$blk"; then echo "ok   RWDM_SOFTMOVE_sensitivity: the residual harness reports a 1e-6 error as 1e-06 (negative control)"
  else echo "FAIL RWDM_SOFTMOVE_sensitivity: a 1e-6 error was not visible"; fail=1; { grep -E '^history:   ' <<<"$blk" || true; } | head -4 | sed 's/^/     residual: /'; fi
}
rwdm_softmove_sens
